import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"
import { drizzle } from "drizzle-orm/node-postgres"
import pg from "pg"
import * as schema from "./schema/index.ts"

// Matches docker-compose.yml at the repo root
export const defaultDatabaseUrl = "postgres://flowpocus:flowpocus@localhost:5432/flowpocus"

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL ?? defaultDatabaseUrl })

export const db = drizzle(pool, { schema })

// SQL migrations generated by `db:generate`, applied by `db:migrate` and by tests
export const migrationsFolder = resolve(dirname(fileURLToPath(import.meta.url)), "../drizzle")

export type DatabaseClient = typeof db
